package config

import (
  "encoding/json"
  "os"
)

func Load(path string) (*Config, error) {
  f, err := os.Open(path)
  if err == nil {
    defer f.Close()
    var raw rawConfig
    if err := json.NewDecoder(f).Decode(&raw); err == nil {
      cfg, err := raw.normalize()
      if err == nil {
        if err := cfg.Validate(); err == nil {
          return cfg, nil
        } else {
          return nil, err
        }
      } else {
        return nil, err
      }
    } else {
      return nil, err
    }
  } else {
    return nil, err
  }
}

