func Load(path string) (*Config, error) {
  f, err := os.Open(path)
  if err != nil {
    return nil, err
  }
  defer f.Close()

  var raw rawConfig
  if err := json.NewDecoder(f).Decode(&raw); err != nil {
    return nil, err
  }
  cfg, err := raw.normalize()
  if err != nil {
    return nil, err
  }
  if err := cfg.Validate(); err != nil {
    return nil, err
  }
  return cfg, nil
}
